<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/ai-usage-report-v1.php';
require_login();
$user=current_user();$pdo=db();
if(!$user||!$pdo){flash('error','Account unavailable.');redirect(url('/login.php'));}
if(!ai_usage_accounting_v032_schema_ready($pdo)){
    if(has_permission('users.manage',$user))redirect(url('/upgrade.php'));
    flash('error','AI usage history is unavailable until an administrator completes the database upgrade.');redirect(url('/subscription.php'));
}
$state=vp3_ai_usage_report_v1($pdo,(int)$user['id'],$_GET);$options=$state['options'];$summary=$state['summary'];$overall=$state['overall'];
$balance=function_exists('subscription_ai_balance')?subscription_ai_balance($user,$pdo):['unlimited'=>false,'remaining'=>0];
$sourceLabels=['homeserver_local'=>'HomeServer Local','user_provider'=>'Personal API','vp3_cloud'=>'System API','vp3_retrieval'=>'Retrieval','vp3_tool'=>'Tool'];
$periodLabels=['month'=>'This month','today'=>'Today','all'=>'All time'];
$viewLabels=['providers'=>'Provider API calls','all'=>'All executions','local'=>'Local & tools'];
$costLabel=ai_usage_accounting_v032_format_aggregate_cost((int)$summary['estimated_cost_micros'],(int)$summary['unknown_cost_requests']);
if((int)$summary['unknown_cost_requests']>0&&(int)$summary['estimated_cost_micros']===0)$costLabel='Unavailable';
$pageUrl=static fn(int $page):string=>url('/ai-usage.php?'.http_build_query(array_merge($options,['page'=>$page])));
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Usage | VP3</title>
<link rel="stylesheet" href="<?= e(url('/chat.css?v=82')) ?>"><link rel="stylesheet" href="<?= e(url('/account.css?v=account-light-20260904')) ?>"><link rel="stylesheet" href="<?= e(url('/ai-usage-v1.css?v=1')) ?>">
</head><body><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='ai_usage';require __DIR__.'/includes/workspace-sidebar-v82.php';?><div class="chat-sidebar-backdrop" id="chatSidebarBackdrop"></div>
<main class="chat-main account-chat-main"><header class="chat-topbar"><button class="chat-icon-button mobile-only" id="openChatSidebar" type="button" aria-label="Open sidebar">☰</button><div class="chat-topbar-title"><strong>AI Usage</strong><span>Provider calls, tokens and cost estimates</span></div></header>
<section class="account-canvas"><div class="account-canvas-inner usage-wrap">
<section class="account-canvas-hero"><div><span>Usage Ledger</span><h1>Your AI usage, accounted for.</h1><div class="account-canvas-meta"><span><?= !empty($balance['unlimited'])?'Unlimited VP3 plan':number_format((int)($balance['remaining']??0)).' VP3 tokens available' ?></span></div></div><div class="usage-actions"><a class="usage-btn" href="<?= e(url('/ai-usage-export-v032.php')) ?>">Export CSV</a><a class="usage-btn" href="<?= e(url('/subscription.php')) ?>">Plan & Usage</a></div></section>
<section class="usage-toolbar" aria-label="Usage filters"><form method="get" class="usage-filters"><label>Period<select name="period"><?php foreach($periodLabels as $key=>$label):?><option value="<?= e($key) ?>"<?= $options['period']===$key?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><label>Show<select name="view"><?php foreach($viewLabels as $key=>$label):?><option value="<?= e($key) ?>"<?= $options['view']===$key?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><button class="usage-btn" type="submit">Apply</button></form><span class="usage-muted"><?= number_format((int)$overall['provider_requests']) ?> API calls · <?= number_format((int)$overall['local_requests']) ?> local/tool runs · UTC</span></section>
<div class="usage-stats"><article class="usage-stat"><span><?= e($viewLabels[$options['view']]) ?></span><strong><?= number_format((int)$summary['requests']) ?></strong><small><?= e($periodLabels[$options['period']]) ?></small></article><article class="usage-stat"><span>Reported model tokens</span><strong><?= number_format((int)$summary['total_tokens']) ?></strong><small><?= (int)$summary['unknown_usage_requests']>0?number_format((int)$summary['unknown_usage_requests']).' calls with usage unreported':'Provider-reported usage' ?></small></article><article class="usage-stat"><span>VP3 tokens charged</span><strong><?= number_format((int)$summary['cloud_tokens']) ?></strong><small>Monthly package + token credits</small></article><article class="usage-stat"><span>Estimated provider cost · USD</span><strong><?= e($costLabel) ?></strong><small><?= (int)$summary['unknown_cost_requests']>0?number_format((int)$summary['unknown_cost_requests']).' calls without a cost estimate':'Using configured model rates' ?></small></article></div>
<p class="usage-note">Provider cost estimates are separate from your VP3 token balance and provider invoices. “Unpriced” means no matching model rate is configured; “Usage unreported” means the provider did not return enough token detail. HomeServer-local, retrieval and tool results use no VP3 cloud tokens. Older recorded subscription usage is included where an execution record was missing; its estimates use configured rates. Calls with no saved usage record cannot be reconstructed.</p>
<section class="usage-card"><div class="usage-head"><div><h2>By model and execution source</h2><p class="usage-muted"><?= e($periodLabels[$options['period']]) ?> · <?= e($viewLabels[$options['view']]) ?></p></div></div><div class="usage-table-wrap"><table class="usage-table"><thead><tr><th>Source</th><th>Provider / model</th><th>Calls / runs</th><th>Reported tokens</th><th>VP3 charged</th><th>Estimated cost</th></tr></thead><tbody>
<?php foreach($state['by_model'] as $row):?><tr><td><span class="usage-pill"><?= e($sourceLabels[$row['source']]??$row['source']) ?></span></td><td><?= e(trim((string)$row['provider'].' / '.(string)$row['model'],' /')) ?: '—' ?></td><td><?= number_format((int)$row['requests']) ?></td><td><?= number_format((int)$row['total_tokens']) ?><?php if((int)$row['unknown_usage_requests']>0):?><small><?= number_format((int)$row['unknown_usage_requests']) ?> usage unreported</small><?php endif;?></td><td><?= number_format((int)$row['cloud_tokens']) ?></td><td><?= e((int)$row['estimated_cost_micros']===0&&(int)$row['unknown_cost_requests']>0?'Unavailable':ai_usage_accounting_v032_format_aggregate_cost((int)$row['estimated_cost_micros'],(int)$row['unknown_cost_requests'])) ?></td></tr><?php endforeach;?>
<?php if(!$state['by_model']):?><tr><td colspan="6">No matching usage in this period. Select All executions to include local tools and retrieval.</td></tr><?php endif;?></tbody></table></div></section>
<section class="usage-card"><div class="usage-head"><div><h2>Recent execution history</h2><p class="usage-muted"><?= number_format((int)$summary['requests']) ?> matching records · <?= $state['per_page'] ?> per page</p></div><span class="usage-muted">Page <?= $options['page'] ?> of <?= $state['pages'] ?></span></div><div class="usage-table-wrap"><table class="usage-table"><thead><tr><th>When · UTC</th><th>Source / service</th><th>Provider / model</th><th>Model tokens</th><th>VP3 charged</th><th>Estimated cost</th><th>Status</th></tr></thead><tbody>
<?php foreach($state['recent'] as $row):?><tr><td class="usage-nowrap"><?= e((string)$row['created_at']) ?></td><td><span class="usage-pill"><?= e($sourceLabels[$row['source']]??$row['source']) ?></span><?php if($serviceLabel=ai_usage_accounting_v032_service_label($row)):?><small><?= e($serviceLabel) ?></small><?php endif;?><?php if($row['origin']==='subscription'):?><small>Recovered subscription record</small><?php endif;?></td><td><?= e(trim((string)$row['provider'].' / '.(string)$row['model'],' /')) ?: '—' ?></td><td><?= e(ai_usage_accounting_v032_token_label($row)) ?></td><td><?= number_format((int)$row['cloud_tokens_charged']) ?></td><td><?= e(vp3_ai_usage_report_cost_label_v1($row)) ?></td><td><?= e(match($row['service_status']){'pending'=>'Running','rejected'=>'Rejected','failed'=>'Failed','unknown'=>'Usage unknown',default=>'Completed'}) ?><?php if((string)$row['failure_class']!==''&&(string)$row['failure_class']!=='none'):?><small><?= e((string)$row['failure_class']) ?></small><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$state['recent']):?><tr><td colspan="7">No matching executions have been recorded.</td></tr><?php endif;?></tbody></table></div><nav class="usage-pagination" aria-label="Usage history pages"><?php if($options['page']>1):?><a class="usage-btn" rel="prev" href="<?= e($pageUrl($options['page']-1)) ?>">Previous</a><?php endif;?><?php if($options['page']<$state['pages']):?><a class="usage-btn" rel="next" href="<?= e($pageUrl($options['page']+1)) ?>">Next</a><?php endif;?></nav></section>
</div></section></main></div><script src="<?= e(url('/chat.js?v=82')) ?>"></script></body></html>
